\set ON_ERROR_STOP on
select t.admin_db();
\echo == PAR1. _classificar contra os casos de referência
select t.ok((select diferenca = 0 and status = 'no_horario' from public._classificar('entrada', '08:00', 480, 5, 30)), 'classificar: entrada pontual');
select t.ok((select diferenca = -5 and status = 'no_horario' from public._classificar('entrada', '08:00', 475, 5, 30)), 'classificar: entrada 5 min antes (tolerância)');
select t.ok((select diferenca = 5 and status = 'no_horario' from public._classificar('entrada', '08:00', 485, 5, 30)), 'classificar: entrada 5 min depois (limite da tolerância)');
select t.ok((select diferenca = 6 and status = 'tolerancia' from public._classificar('entrada', '08:00', 486, 5, 30)), 'classificar: entrada 6 min depois');
select t.ok((select diferenca = 29 and status = 'tolerancia' from public._classificar('entrada', '08:00', 509, 5, 30)), 'classificar: entrada 29 min depois');
select t.ok((select diferenca = 30 and status = 'atraso' from public._classificar('entrada', '08:00', 510, 5, 30)), 'classificar: entrada 30 min depois = atraso');
