select t.ok((select diferenca = 3 and status = 'no_horario' from public._classificar('retorno_intervalo', '14:00', 843, 5, 30)), 'classificar: retorno do intervalo no horário');
select t.ok((select diferenca = -10 and status = 'tolerancia' from public._classificar('saida_intervalo', '12:00', 710, 5, 30)), 'classificar: saída para intervalo adiantada 10 min');
select t.ok((select diferenca = -30 and status = 'saida_antecipada' from public._classificar('saida_intervalo', '12:00', 690, 5, 30)), 'classificar: saída para intervalo 30 min antes = antecipada');
select t.ok((select diferenca = 0 and status = 'no_horario' from public._classificar('saida', '18:00', 1080, 5, 30)), 'classificar: saída no horário');
select t.ok((select diferenca = 3 and status = 'no_horario' from public._classificar('saida', '18:00', 1083, 5, 30)), 'classificar: saída 3 min depois');
