select t.ok((select diferenca = 120 and status = 'extra' from public._classificar('saida', '18:00', 1200, 5, 30)), 'classificar: saída 2h depois = extra');
select t.ok((select diferenca = -15 and status = 'tolerancia' from public._classificar('saida', '18:00', 1065, 5, 30)), 'classificar: saída 15 min antes = tolerância');
select t.ok((select diferenca = -30 and status = 'saida_antecipada' from public._classificar('saida', '18:00', 1050, 5, 30)), 'classificar: saída 30 min antes = antecipada');
select t.ok((select diferenca = -180 and status = 'saida_antecipada' from public._classificar('saida', '18:00', 900, 5, 30)), 'classificar: saída 3h antes = antecipada');
