select t.ok((select diferenca = 45 and status = 'tolerancia' from public._classificar('entrada', '08:00', 525, 5, 60)), 'classificar: limite configurado em 60 min');
select t.ok((select diferenca = 40 and status = 'atraso' from public._classificar('entrada', '08:00', 520, 5, 30)), 'classificar: jornada contínua de estágio: entrada');
select t.ok((select diferenca = -40 and status = 'saida_antecipada' from public._classificar('saida', '14:00', 800, 5, 30)), 'classificar: jornada contínua de estágio: saída');
